import React from "react";
import { Link } from "react-router-dom";

export default function EventCard({ event }) {
  return (
    <div className="event-card" style={{ width: "250px" }}>
      
      {/* --- IMAGE GOES HERE — this was missing --- */}
      {event.image_url && (
        <img 
          src={event.image_url}
          alt={event.title}
          style={{
            width: "100%",
            height: "160px",
            objectFit: "cover",
            borderRadius: "12px 12px 0 0",
            marginBottom: "12px"
          }}
        />
      )}
      {/* ----------------------------------------- */}

      <h3>{event.title}</h3>
      <p>{event.description}</p>

      <Link to={`/events/${event.id}`} className="event-card-btn">
        View Event
      </Link>
    </div>
  );
}
